v[3].x = 26.0f; v[3].y = 30.0f; v[3].z = 0.1f;
v[3].u = 1.0f;  v[3].v = 1.0f;

// ---- stage 2: sign/abs, normalize (leading-zero), pack ----
module fp_add3_24_s2 (
    input  signed [27:0] ssum,
    input         [7:0]  e_max,
    output        [31:0] y
);
    wire        s_res = ssum[27];                 // result sign
    wire [26:0] mag   = s_res ? (~ssum[26:0] + 27'd1) : ssum[26:0];  // |sum|, 27b

    // The aligned significands have their leading 1 at bit 23. Summing three can
    // carry up to bit 25 (3 * ~2^24 < 2^26). Normalize: find the leading 1 in mag
    // and set the exponent = e_max + (leadingbit - 23).
    reg  [23:0] norm_sig;
    reg  signed [10:0] e_norm;
    integer i; reg found;
    always @(*) begin
        norm_sig = 24'd0;
        e_norm   = $signed({3'b0, e_max});
        found    = 1'b0;
        // check high headroom bits first (carry-outs above bit 23), then bit 23,
        // then leading-zero search downward for cancellation.
        if (mag[26]) begin
            norm_sig = mag[26:3];                 // take 24 bits below leading 1
            e_norm   = $signed({3'b0, e_max}) + 11'sd3;
            found    = 1'b1;
        end else if (mag[25]) begin
            norm_sig = mag[25:2];
            e_norm   = $signed({3'b0, e_max}) + 11'sd2;
            found    = 1'b1;
        end else if (mag[24]) begin
            norm_sig = mag[24:1];
            e_norm   = $signed({3'b0, e_max}) + 11'sd1;
            found    = 1'b1;
        end else if (mag[23]) begin
            norm_sig = mag[23:0];
            e_norm   = $signed({3'b0, e_max});
            found    = 1'b1;

// golden SPANGEN: aligned-4 walk, leading same-tag run capped at group boundary, dedup by
// pc_slot direct-mapped. Records, per run-start pixel: {id,rep,shmask,invw[4],at}.
struct Span { uint32_t idx,id,rep,at; uint32_t invw[4]; };
// per-id expected setup (black-box golden): decoded record + refsw2 planes, filled at id
// bump-allocation. gv[id]=1 when written. ddx/ddy/c[p] are DOUBLE-precision refs (plane p:
// 0=U 1=V 2..5=Col 6..9=Ofs, all *z; U/V iff textured, Ofs iff offset). pvalid[p] marks
// planes the RTL actually computes.
struct SetupGold { bool valid; uint32_t isp,tsp,tcw; bool pvalid[10]; uint32_t ddx[10],ddy[10],c[10]; };
static void golden(const Vec& vc, std::vector<Span>& out,
                   SetupGold* sg=nullptr, uint32_t param_base=0, bool intensity=false,
                   uint32_t leftx=0, uint32_t topy=0){
    // bump-allocated ids: dedup map (direct-mapped by pc_slot) -> {tag, id}; id = top++.
    uint32_t map_valid[1024]={0}, map_tag[1024], map_id[1024]; uint32_t top=0;
    int x=0;
    while(x<1024){
        int lane=x&3;
        uint32_t tag=vc.tag[x];
        int rep=1;
        // POLARITY: the captured header shade_mode is the OLD peel_core convention (=ti_mode:
        // 0=OP, 1=PEEL). spanner_v2's shade_mode is 1=OP(shade-all), 0=PEEL(gate on valid) --
        // the live peel_core feeds it ~ti_mode. So INVERT the header value here (and at the
        // DUT feed below) so the unit test matches how peel_core actually drives the module.
        bool sm_shadeall = (vc.shade_mode == 0);   // OP -> shade all
        auto shok=[&](int p){ return sm_shadeall ? 1u : (vc.valid[p]?1u:0u); };
        // Coalesce (matches spanner_v2): SHADED start extends on shaded + same tag; INVALID
        // start extends on invalid (ignoring tag). Only a SHADED run emits a span; invalid
        // runs just advance x. No shade mask (every emitted span is uniformly shaded).
        bool run_ok0 = shok(x)!=0;
        for(int l=lane+1; l<4; l++){
            bool okl = shok((x&~3)+l)!=0;
            if(okl==run_ok0 && (run_ok0 ? (vc.tag[(x&~3)+l]==tag) : true)) rep++;
            else break;
        }
        if(!run_ok0){ x += rep; continue; }   // invalid run: no span, skip
        uint32_t h=pc_slot(tag), id=0;
        if(map_valid[h] && map_tag[h]==tag){ id=map_id[h]; }              // dedup hit

// ---------------- performance counters (sim only) ----------------
// Two INDEPENDENT classifications (ISP/raster engine, TSP/shade engine), each
// charging every clock to exactly one bucket -> each set sums to pc_total. The two
// engines can be busy the SAME cycle (they overlap), so keeping them separate shows
// real per-engine utilisation. Plus a top-level FSM-state view (pc_top_*). Dumped
// at S_DONE.
integer pc_total;
// ---- SPANNER pipeline probe: are passes/pixels being dropped? ----
// pc_hand  = passes ISP hands to the spanner (ti_ready sets, incl. post-only)
// pc_span  = passes the spanner finishes (P_DONE + post-only, sets sb_ready)
// pc_drain = passes the reader finishes (R_DRAIN + R_POST)
// pc_blend = pixels blended into u_col (cb_valid pulses)
// pc_swrite= span-buffer writes with shade=1 (pixels the spanner marked shaded)
// If pc_hand != pc_span != pc_drain -> passes dropped. If pc_swrite != pc_blend
// (over the run) -> per-pixel drop between span-fill and blend.
integer pc_hand, pc_span, pc_drain, pc_blend, pc_swrite;
// pc_prefetch = SCAN-prefetches issued (a next-miss found -> u_prefetch started
// under P_TSP_RUN's SETUP_WAIT). pc_pf_hit = demand misses SERVED from the prefetch
// shadow (pf_ready && pf_rtag==tag) -> zero demand fetch. Best-effort overlap metric.
integer pc_prefetch, pc_pf_hit;
integer pc_pf_wasted;   // a READY shadow clobbered by a new prefetch, never consumed
// miss-classification leak counters: why a demand miss did NOT promote.
integer pc_m_promote;   // shadow ready + tag match at miss (zero-wait hit)
integer pc_m_waithit;   // prefetch in flight -> P_PF_WAIT -> matched (hit after wait)
integer pc_m_waitmiss;  // prefetch in flight -> P_PF_WAIT -> WRONG tag -> demand fetch
integer pc_m_cold;      // no prefetch in flight/ready -> straight demand fetch
// ISP / raster engine (classified by rs_st)
integer pc_ras_active;      // RS_RAS: rasterizing chunks
integer pc_ras_pop;         // RS_POP: plane-FIFO pop + splice
integer pc_ras_drain;       // RS_DRAIN: raster pipe drain
integer pc_ras_idle;        // RS_IDLE: not rasterizing (waiting / nothing to do)
integer pc_ras_corner;      // RS_CORNER: per-triangle 4-corner probe wait (8 cyc/tri)
integer pc_corner_cull;     // triangles trivially rejected by the 4-corner test
integer pc_sort_skip;       // triangles skipped by the sort cache (fully rendered)

tsp_setup_stream u_tsp (
    // .rdy: back-to-back handshake unused here - spanner_v2 waits for done
    // (done implies rdy), so the legacy start-after-done flow still works.
    .clk(clk), .reset(reset), .start(tsp_start), .rdy(), .done(tsp_done),
    .gouraud(f_gouraud), .texture(f_texture), .offset(f_offset),
    .x1(fv_x[0]),.y1(fv_y[0]),.z1(fv_z[0]),
    .x2(fv_x[1]),.y2(fv_y[1]),.z2(fv_z[1]),
    .x3(fv_x[2]),.y3(fv_y[2]),.z3(fv_z[2]),
    .xbase(xbase), .ybase(ybase),
    .u1(fv_u[0]),.v1(fv_v[0]),.u2(fv_u[1]),.v2(fv_v[1]),.u3(fv_u[2]),.v3(fv_v[2]),
    .col1(fv_col[0]),.col2(fv_col[1]),.col3(fv_col[2]),
    .ofs1(fv_ofs[0]),.ofs2(fv_ofs[1]),.ofs3(fv_ofs[2]),
    .plane_valid(tsp_pvalid), .plane_idx(tsp_pidx),
    .o_ddx(tsp_pddx), .o_ddy(tsp_pddy), .o_c(tsp_pc)
);

// plane accumulators (written by tsp_setup_min's streamed plane_valid/plane_idx)
reg [319:0] acc_ddx, acc_ddy, acc_c;

// ============================ combinational OUT + FIFO drive ============================
integer k;
always @(*) begin
    // ----- EMIT: span write + FIFO push. The descriptor produced by COAL last cycle
    // is in t_* (t_valid); its slot read has resolved -> dedup here and write. Held
    // (no write, no advance) when the pipeline is frozen. -----
    // emit a span ONLY for a shaded run (t_ok); invalid runs retire silently.
    sp_we      = run_shaded && !pipe_stall;
    sp_slot    = span_head[SPAN_W-1:0]; // ring write slot = span_head (wraps)
    sp_start   = t_x;                  // run-start pixel index (y:x) [data for the reader]
    sp_id      = emit_id;              // bump-allocated (or reused) ring id
    sp_rep     = t_rep;
    sp_at      = t_at;
    for (k = 0; k < 4; k = k + 1) sp_invw[k] = t_invw[k];
    // span RING range of this pass (valid at busy->0). base = span_head at pass start,
    // cnt = span_head - base (wrap-safe via the extra MSB). cnt==0 => empty pass.
    sp_range_base = span_pass_base;
    sp_range_cnt  = span_head - span_pass_base;

    .out_valid(uv_ov),
    .c00u(c00u),.c00v(c00v),.c01u(c01u),.c01v(c01v),
    .c10u(c10u),.c10v(c10v),.c11u(c11u),.c11v(c11v),.ufrac(ufr),.vfrac(vfr));
// corners are {cu0,cu1} x {cv0,cv1}: cu1=c00u, cu0=c01u, cv1=c00v, cv0=c11v.
wire [9:0] cu0 = c01u[9:0], cu1 = c00u[9:0];
wire [9:0] cv0 = c11v[9:0], cv1 = c00v[9:0];

// ============================================================================
// STAGE BASE (comb): per-pixel shared addressing. Fed by the SAME cycle's config
// (config is per-pixel constant; delayed by UVMAP latency to align with uv_ov).
// ============================================================================
// delay the per-pixel config by UVMAP latency (3) so it aligns with uv_ov.
localparam integer UVLAT = 3;
reg [20:0] d_texaddr [0:UVLAT-1];
reg [2:0]  d_texu    [0:UVLAT-1], d_texv [0:UVLAT-1];
reg [3:0]  d_mip     [0:UVLAT-1];
reg [2:0]  d_pixfmt  [0:UVLAT-1];
reg [1:0]  d_palfmt  [0:UVLAT-1];
reg [5:0]  d_palsel  [0:UVLAT-1];
reg [4:0]  d_tctrl   [0:UVLAT-1];
reg [1:0]  d_filt    [0:UVLAT-1];
reg        d_tex[0:UVLAT-1], d_vq[0:UVLAT-1], d_scan[0:UVLAT-1],
           d_strd[0:UVLAT-1], d_mm[0:UVLAT-1], d_igna[0:UVLAT-1];
reg [IDW-1:0] d_id [0:UVLAT-1];
always @(posedge clk) if (!front_stall) begin
    d_texaddr[0]<=tex_addr_in; d_texu[0]<=texu; d_texv[0]<=texv; d_mip[0]<=miplevel;
    d_pixfmt[0]<=pixfmt; d_palfmt[0]<=pal_fmt; d_palsel[0]<=palsel; d_tctrl[0]<=text_ctrl;
    d_filt[0]<=filter_mode; d_tex[0]<=tex; d_vq[0]<=vq; d_scan[0]<=scan;
    d_strd[0]<=stride_sel; d_mm[0]<=mipmapped; d_igna[0]<=ignore_texa; d_id[0]<=in_id;
    for (d=1; d<UVLAT; d=d+1) begin
        d_texaddr[d]<=d_texaddr[d-1]; d_texu[d]<=d_texu[d-1]; d_texv[d]<=d_texv[d-1];
        d_mip[d]<=d_mip[d-1]; d_pixfmt[d]<=d_pixfmt[d-1]; d_palfmt[d]<=d_palfmt[d-1];
        d_palsel[d]<=d_palsel[d-1]; d_tctrl[d]<=d_tctrl[d-1]; d_filt[d]<=d_filt[d-1];
        d_tex[d]<=d_tex[d-1]; d_vq[d]<=d_vq[d-1]; d_scan[d]<=d_scan[d-1];
        d_strd[d]<=d_strd[d-1]; d_mm[d]<=d_mm[d-1]; d_igna[d]<=d_igna[d-1]; d_id[d]<=d_id[d-1];

assign tex_dresp[0].busy=d_busy||pend[0]; assign tex_dresp[1].busy=d_busy||pend[1];
assign ts_dresp.busy=d_busy||pend[2]; assign pr_dresp.busy=d_busy||pend[3];
assign ol_dresp.busy=d_busy||pend[4]; assign ra_dresp.busy=d_busy||pend[5];
assign tex_dresp[0].dout=ddr_resp.dout; assign tex_dresp[1].dout=ddr_resp.dout;
assign ts_dresp.dout=ddr_resp.dout; assign pr_dresp.dout=ddr_resp.dout;
assign ol_dresp.dout=ddr_resp.dout; assign ra_dresp.dout=ddr_resp.dout;
assign tex_dresp[0].dready=ddr_resp.dready&&(d_owner==3'd0);
assign tex_dresp[1].dready=ddr_resp.dready&&(d_owner==3'd1);
assign ts_dresp.dready=ddr_resp.dready&&(d_owner==3'd2);
assign pr_dresp.dready=ddr_resp.dready&&(d_owner==3'd3);
assign ol_dresp.dready=ddr_resp.dready&&(d_owner==3'd4);
assign ra_dresp.dready=ddr_resp.dready&&(d_owner==3'd5);

// ---- 4 injected palette RAMs (1024x32, 1-cycle registered read) ----
wire [9:0]  pal_addr [0:3];
reg  [31:0] pal_data [0:3];
genvar pgi;
generate for (pgi=0; pgi<4; pgi=pgi+1) begin : pal
    (* ramstyle = "M10K" *) reg [31:0] pram [0:1023];
    integer pj; initial for (pj=0;pj<1024;pj=pj+1) pram[pj]={8'hFF, pj[7:0], pj[9:2], pj[7:0]};
    always @(posedge clk_100m) pal_data[pgi] <= pram[pal_addr[pgi]];
end endgenerate

// ==================================================================
// INPUT REGISTER BANK. 10 planes x 3 (ddx/ddy/c) = 30 words + scalars.
//   0..9   : in_ddx[0..9]
//   10..19 : in_ddy[0..9]
//   20..29 : in_c  [0..9]
//   30     : invw_in
//   31     : tsp
//   32     : tcw
//   33     : { pp_offset[28], pp_texture[27], in_valid[26], text_ctrl[25:21],
//             py[20:16], px[15:11], in_id[IDW-1:0] }
//   34     : { pal_fmt[1:0] }
// ==================================================================
localparam integer NREG = 36;

Verilated::commandArgs(argc,argv);
const char* inpath   = (argc>1)? argv[1] : "tsp_test_traces.txt";
const char* vrampath = (argc>2)? argv[2] : "dumps/vram_menu2.bin";
const char* regspath = (argc>3)? argv[3] : "dumps/pvr_regs_menu2.bin";
// per-channel ARGB tolerance (default 0 = bit-exact). The v2 tex_filter uses a raw
// >>8 bilinear weight while the known-good reference uses to_u8_256/65536, so textured
// pixels can differ by a few LSB per channel WITHOUT being a real bug. TOL=<N> counts
// any pixel whose every channel is within N as a pass; it still reports exact hits too.
int tol = 0;
{ const char* t = getenv("TOL"); if(t) tol = atoi(t); }

// ---- read the trace (inputs + expected outputs) ----
FILE* f=fopen(inpath,"r");
if(!f){ printf("cannot open %s\n",inpath); return 2; }
std::vector<In> pix;
char line[4096];
while(fgets(line,sizeof(line),f)){
    if(line[0]=='#') continue;
    // split at the ' | ' separator between inputs and expected outputs
    char* bar = strstr(line," | ");
    if(!bar) continue;
    *bar = '\0';
    char* outs = bar+3;
    In p; unsigned seq;
    int n=sscanf(line,"%u %u %u %u %x %x %x %x %u %u"
                      " %x %x %x %x %x %x %x %x %x %x"
                      " %x %x %x %x %x %x %x %x %x %x"
                      " %x %x %x %x %x %x %x %x %x %x",
        &seq,&p.id,&p.px,&p.py,&p.invw,&p.tsp,&p.tcw,&p.tc,&p.ptx,&p.pof,
        &p.ddx[0],&p.ddx[1],&p.ddx[2],&p.ddx[3],&p.ddx[4],&p.ddx[5],&p.ddx[6],&p.ddx[7],&p.ddx[8],&p.ddx[9],
        &p.ddy[0],&p.ddy[1],&p.ddy[2],&p.ddy[3],&p.ddy[4],&p.ddy[5],&p.ddy[6],&p.ddy[7],&p.ddy[8],&p.ddy[9],
        &p.c[0],&p.c[1],&p.c[2],&p.c[3],&p.c[4],&p.c[5],&p.c[6],&p.c[7],&p.c[8],&p.c[9]);
    int m=sscanf(outs,"%u %x %x",&p.exp_id,&p.exp_argb,&p.exp_tsp);
    if(n==40 && m==3) pix.push_back(p);

// Handshake: parser raises entry_ready with fields stable; the consumer
// processes the WHOLE entry (e.g. iterating every set mask bit / every
// array index itself) and pulses entry_done (1 cycle) when done with it;
// the parser then drops entry_ready and advances to the next list entry.
typedef struct packed {
    logic           entry_ready;   // LEVEL: an entry is presented + stable
    entry_type_e    entry_type;    // ENT_STRIP / ENT_TRI / ENT_QUAD
    objlist_entry_t entry;         // decoded object-list entry fields
} prim_out_t;
typedef struct packed {
    logic      entry_done;   // 1-cycle: consumer finished this entry
} prim_ack_t;

// one decoded vertex (raw 32-bit param words placed into named fields;
// float/format interpretation is left to the consumer). UV/ofs are only
// meaningful when the record's isp word enables Texture/Offset. Produced by
// param_fetch (tag -> header + vertices), NOT by object_list_parser.
typedef struct packed {
    logic [31:0] x, y, z;      // position (raw float bits)
    logic [31:0] u, v;         // texture coords (raw; f16 pair packed in u if UV_16b)
    logic [31:0] col;          // base colour (packed ARGB word)
    logic [31:0] ofs;          // offset colour (packed word)
} vtx_words_t;

// ---- region_array_parser output: one STATE at a time per tile ----
// For each region-array entry (tile), the parser strobes the tile's enabled
// states in order (clear -> op -> pt -> tr -> flush), one per handshake:
// it raises state_ready (LEVEL) with tile x/y, a one-hot `state`, and (for
// op/pt/tr) the list base pointer (byte addr = ListPointer.ptr_in_words*4);
// the consumer processes that state and pulses list_done (1-cycle); the
// parser then advances to the tile's next enabled state, or the next tile.
// A tile with NO enabled states is silently skipped. tiles_parsed pulses
// when the whole region array is consumed (control.last_region, or after
// 16384 tiles as a runaway guard). ptr is 0 for clear/flush (no list).

endfunction
wire [3:0] ex_strip_nv = 4'd8 - {1'b0, lsb6(ex_mask)};   // 3..8
wire [3:0] ex_nverts   = ex_array ? (ex_quad ? 4'd4 : 4'd3) : ex_strip_nv;

// ---- per-ENTRY geometry pre-computation (2 shallow stages) ----
// The record geometry (stride/hdr/span/rec_bytes/rec_words) is CONSTANT for the
// whole entry (shadow/skip/mask/array never change between an array entry's
// records), but computing it combinationally at the record-start latch put the
// whole ex_shadow -> stride-mux -> (nverts-1)*stride multiply cone (plus the
// parallel 3*stride rec_bytes multiply) into that one cycle - the ~15ns
// ex_shadow -> rd_span_r Fmax violator. Split it per ENTRY instead:
//   E+1 (exg_s1_v): register the shallow terms (stride, hdr, nverts-1) off ex_*.
//   E+2 (exg_v)   : register the products (span, rec_bytes, rec_words) off the
//                   STAGE-1 REGISTERS - each multiply gets its own clean cycle.
// Record start then copies plain registers (no logic). Costs +2 cycles per
// entry, amortized over all its records.
reg        exg_s1_v, exg_v;
reg [4:0]  exg_stride_r, exg_hdr_r;
reg [3:0]  exg_nm1_r;                       // nverts - 1
reg [8:0]  exg_span_r;
reg [26:0] exg_recb_r;
reg [20:0] exg_recw_r;
// stage-2 combinational (from stage-1 registers; same expressions/widths as the
// old ex_span_vw / ex_rec_bytes / ex_rec_words, only the sources changed).
// rec_bytes = (hdr + nverts*stride)*4 with nverts*stride = nm1*stride + stride,
// sharing the one nm1*stride product with the span (was a hard-coded 3*stride,
// wrong for QUAD arrays which carry 4 vertices per record).
wire [8:0]  exg_nvs_c  = {5'b0, exg_nm1_r} * {4'b0, exg_stride_r};   // (nverts-1)*stride
wire [8:0]  exg_span_c = {4'b0, exg_hdr_r} + exg_nvs_c + 9'd3;
wire [26:0] exg_recb_c = {22'b0, exg_hdr_r, 2'b00}
                       + {16'b0, exg_nvs_c, 2'b00}
                       + {20'b0, exg_stride_r, 2'b00};
wire [20:0] exg_recw_c = exg_recb_c[22:2];

    if(++cyc>TIMEOUT){ printf("pass %d: TIMEOUT (busy stuck) after %ld cyc\n",n,cyc); total_fail++; goto next; }
}
// a couple trailing ticks so the last ts write lands
tick(); tick();
total_cyc += cyc;
// practical: a tile can't finish faster than its shade stage (1024px @1px/clk), so
// a fast spanner tile is floored at 1024 - spare time can't offset a slow tile.
practical_cyc += (cyc < 1024) ? 1024 : cyc;
total_runs += ROOT->spanner_v2_tb_top__DOT__setup_runs;

{
    std::vector<Span> gold;
    static SetupGold sgold[1024];
    for(int i=0;i<1024;i++) sgold[i].valid=false;
    golden(vc, gold, g_planecheck?sgold:nullptr,
           vc.param_base, vc.intensity!=0, vc.xbase, vc.ybase);

    int fails=0;
    // 1) DENSELY PACKED spans: gold[] is in SPANGEN emission order == the DUT's dense
    // slots. Compare slot-by-slot (slot k = the k-th emitted span), including the
    // run-start pixel (spo_x = sp_idx data). Then check the span COUNT via sp_last.
    for(size_t k=0;k<gold.size();k++){
        const Span& s=gold[k];
        if(!SPO_VALID[k]){
            if(fails<10) printf("pass %d: MISSING span at slot %zu (x=%u id=%u rep=%u)\n",n,k,s.idx,s.id,s.rep);
