    i2_pixfmt<=i1_pixfmt; i2_palfmt<=i1_palfmt; i2_scan<=i1_scan; i2_twid<=i1_twid; i2_palsel<=i1_palsel;
    i2_uf<=i1_uf; i2_vf<=i1_vf; i2_filt<=i1_filt; i2_igna<=i1_igna; i2_tex<=i1_tex; i2_id<=i1_id;
    // stage 3: offset-register -> address-register cycle (r_iss)
    i_pixfmt<=i2_pixfmt; i_palfmt<=i2_palfmt; i_scan<=i2_scan; i_twid<=i2_twid; i_palsel<=i2_palsel;
    i_uf<=i2_uf; i_vf<=i2_vf; i_filt<=i2_filt; i_igna<=i2_igna; i_tex<=i2_tex; i_id<=i2_id;

localparam integer PLD = 64, PLAW = 6;
// ---- M10K FWFT payload FIFO ----
// The body lives in block RAM; only the HEAD is a register. A head register is
// unavoidable rather than a style choice: pl_out is consumed COMBINATIONALLY in
// the same cycle tu_ov fires, and tu_ov is tex_unit's result-valid - it cannot be
// back-pressured and is not known a cycle ahead. A plain registered-read FIFO
// would therefore deliver the payload one cycle late on EVERY pop (depth does not
// help; read latency is not a function of occupancy). Keeping the head in a
// register and refilling it from the RAM behind is exactly what makes the pop
// zero-latency - i.e. FWFT.
//   Read-ahead: raddr is the pointer we will load NEXT (pl_rp_nxt), not the
//   current one, so back-to-back pops stream at 1/cycle instead of alternating.
//   Write bypass: an entry pushed at cycle T cannot be read out of the RAM at
//   T+1 (same-address read-during-write returns the pre-write value), so the
//   just-written datum is forwarded from a 1-deep register. This is the path the
//   empty->push->pop sequence takes, which is every tex-pipe restart.
wire [PLW-1:0]  pl_q;
reg  [PLW-1:0]  pl_hd;      reg pl_hd_v;      // FWFT head
reg  [PLAW:0]   pl_wp, pl_rp;                 // extra MSB disambiguates full/empty
reg  [PLAW:0]   pl_cnt;
wire pl_push = tu_issue;                    // push on front issue (== tex_unit accept)
// Pop on a tex_unit result, but NEVER when the FIFO is empty. In steady state a tu_ov
// always has a matching prior push (tex_unit is in-order & lossless), so this gate is a
// no-op there. It ONLY suppresses spurious tu_ov pulses during the reset/startup window
// (the whole pipe momentarily shows out_valid=1 before it settles) that would otherwise
// underflow pl_cnt (0 - N wraps to ~127), latch pl_room=0, and deadlock the front.
wire pl_pop  = tu_ov && (pl_cnt != 0);
wire pl_head_free = !pl_hd_v || pl_pop;       // head slot can take a new entry
wire pl_ram_has   = (pl_wp != pl_rp);         // an entry sits in the RAM body
wire [PLAW:0] pl_rp_nxt = (pl_head_free && pl_ram_has) ? pl_rp + 1'b1 : pl_rp;
// 1-deep write forwarding (see the read-during-write note above)
reg  [PLW-1:0] pl_pw_d; reg [PLAW:0] pl_pw_a; reg pl_pw_v;
wire [PLW-1:0] pl_src = (pl_pw_v && (pl_pw_a == pl_rp)) ? pl_pw_d : pl_q;
bram_sdp #(.W(PLW), .D(PLD)) u_plf (
    .clk(clk), .we(pl_push), .waddr(pl_wp[PLAW-1:0]), .din(pl_in),
    .re(1'b1),  .raddr(pl_rp_nxt[PLAW-1:0]), .q(pl_q));
wire [PLW-1:0] pl_out = pl_hd;
assign pl_room = (pl_cnt < PLD-4);

wire  [9:0] look_src = look_shf[9:0];
wire [11:0] look_key = {look_rgn, look_src};

// game-line fetch length: whole beats covering the FB-view bytes of one
// line (raw layout doubles in split mode), +1 for the 888 packed quirk
// (one byte past SRC_W*3 can be read), +1 when the base is mid-beat
wire  [3:0] look_roff  = split_lat ? {1'b0, fbs_stable[3], 2'b00}
                                   : fbs_stable[3:0];
/* verilator lint_off WIDTHTRUNC */
wire  [8:0] bb_lin     = pd_lat
                       ? ((dep_lat == 2'd2) ? SRC_W*3/32     // 60 (960 bytes)
                        : (dep_lat == 2'd3) ? SRC_W/8        // 80
                                            : SRC_W/16)      // 40
                       : ((dep_lat == 2'd2) ? SRC_W*3/16     // 120 (1920 bytes)
                        : (dep_lat == 2'd3) ? SRC_W/4        // 160
                                            : SRC_W/8);      // 80
/* verilator lint_on WIDTHTRUNC */
wire  [8:0] bb_geo     = split_lat ? {bb_lin[7:0], 1'b0} : bb_lin;
wire  [8:0] look_beats = bb_geo + {8'd0, look_roff != 4'd0};

// look_* are LINE-CONSTANT (vcnt only changes when hcnt wraps): register the
// whole lookahead cone per clock (copies are settled from hcnt==1 on) and
// fire the request at hcnt==2 instead of hcnt==0, so the vcnt+2 wrap adder /
// region subtracts / 12-bit dedup compare never gate the req_* enables
// combinationally (they were an STA-failing family into req_base). The two
// pixel clocks of extra latency are nothing against the ~2-output-line
// fetch-ahead margin, and the per-line config latches at hcnt==0 have
// settled a full cycle before the registered copies are consumed.
reg        look_in_r    = 1'b0;
reg [11:0] look_key_r   = 12'hFFF;
reg  [1:0] look_rgn_r   = 2'd0;
reg        look_sof_r   = 1'b0;
reg        look_buf_r   = 1'b0;
reg        look_game_r  = 1'b0;
reg  [3:0] look_roff_r  = 4'd0;
reg  [8:0] look_beats_r = 9'd0;
always @(posedge clk) begin
    look_in_r    <= look_in;
    look_key_r   <= look_key;
    look_rgn_r   <= look_rgn;

reg [1:0] s1_w0lo = 2'd0, s2_w0lo = 2'd0;   // window rotation, piped with the RAM
reg [1:0] s1_blo  = 2'd0, s2_blo  = 2'd0;   // byte offset within the window
reg [4:0] pipe1   = 5'd0;   // {img, de, hs, vs, vbl}

always @(posedge clk) begin
    // stage 0/1 companions of the RAM pipeline in the generate above
    s1_w0lo <= w0_pre[1:0];
    s1_blo  <= b_pre_r[1:0];
    s2_w0lo <= s1_w0lo;
    s2_blo  <= s1_blo;
    pipe1   <= {img_c, de_c, hs_c, vs_c, vbl_c};

    // stage 2: rotate the window, funnel the pixel's bytes down, convert.
    // dep_lat/cat_lat/en_lat/band_v_r are line-constant, so using them
    // "late" is safe (the affected edge pixels are border-black).
    begin : lane_mux
        reg [31:0] wlo, whi;
        reg [63:0] s64;
        reg [31:0] p32;
        reg [15:0] p16;
        reg  [7:0] r8, g8, b8;
        wlo = rq[s2_w0lo];
        whi = rq[s2_w0lo + 2'd1];
        s64 = {whi, wlo} >> {s2_blo, 3'b000};
        p32 = s64[31:0];
        p16 = p32[15:0];
        if (band_v_r) begin                  // bands: 565, MSB-replicated
            r8 = {p16[15:11], p16[15:13]};
            g8 = {p16[10:5],  p16[10:9]};
            b8 = {p16[4:0],   p16[4:2]};
        end
        else case (dep_lat)
            2'd0: begin                      // 0555, fb_concat appended
                r8 = {p16[14:10], cat_lat};
                g8 = {p16[9:5],   cat_lat};
                b8 = {p16[4:0],   cat_lat};
            end
            2'd1: begin                      // 565, fb_concat appended
                r8 = {p16[15:11], cat_lat};
                g8 = {p16[10:5],  cat_lat[2:1]};

dut = new Vsimplex_pvr_top;
dut->reset = 1;
for (int i = 0; i < 8; i++) tick();
dut->reset = 0;
for (int i = 0; i < 4; i++) tick();

