// ================= pre-fetch sort$ check state =================
// Runs CONCURRENTLY with the exg_* geometry pipeline off the live ex_* cursor
// (ex_po is always the NEXT record to fetch), one verdict per triangle:
//   array record : one tag {ex_po, toff=0}            -> pc_skip
//   strip record : one tag per enabled mask bit       -> pc_fmask (survivors)
// pc_v gates the record start; re-armed (cleared) per record.
reg        pe_en;                  // skip_en latched at entry pull (stable per entry)
reg        pc_v;                   // verdicts complete for the next record
reg        pc_skip;                // array: record fully rendered -> skip fetch
reg [5:0]  pc_fmask;               // strip: enabled AND not-done (same bit order
                                   //        as ex_mask: triangle i at bit [5-i])
reg [2:0]  pc_i;                   // strip triangle index (toff) being checked
localparam PC_IDLE=2'd0, PC_ISSUE=2'd1, PC_WAIT=2'd2;
reg [1:0]  pcs;
// NOTE: pass the per-slot fields IN (read the arrays at the call site) rather
// than indexing them inside the function - Quartus 17.0's Verific frontend
// crashes ("read to RAM wasn't mapped") on an array read via a function-arg
// index inside an assignment-pattern.
function automatic core_tag_t mk_tag(input isp_cbp, input shdw,
                                     input [2:0] skp, input [20:0] po,
                                     input [2:0] toff);
    mk_tag = '{ invalid:1'b0, pad:2'b00,
                cache_bypass:isp_cbp, shadow:shdw, skip:skp,
                param_offs_in_words:po, tag_offset:toff };
endfunction
// check tag: cache_bypass unknown pre-fetch -> 0 (see port comment)
assign chk_tag = mk_tag(1'b0, ex_shadow, ex_skip, ex_po,
                        ex_array ? 3'd0 : pc_i);
// the record about to start is entirely skippable
wire pc_rec_skip = ex_array ? pc_skip : (pc_fmask == 6'd0);
function automatic [2:0] cnt6(input [5:0] m);
    cnt6 = {2'd0,m[0]} + {2'd0,m[1]} + {2'd0,m[2]}
         + {2'd0,m[3]} + {2'd0,m[4]} + {2'd0,m[5]};
endfunction

wire [2:0] depth_mode = isp_word[31:29];
wire       zwrite_dis = isp_word[26];

// `peeling` selects the layer-peel (RM_TRANSLUCENT_AUTOSORT) compare for the
// active raster triangle; OP uses the plain opaque DepthMode compare. Set when
// the active region state is PT or TR (PT treated as TR for now).
reg        peeling;

// ---- raster consumer stage-A -> stage-B pipeline (registered read in u_peel) ----
// Stage A (on ras_out_valid): u_peel presents the peel-RAM READ for the resolved
// chunk. Stage B (next cycle, b_valid): u_peel feeds back the read chunk, runs its
// internal depth compare off the latched b_* fields, and writes back the passing
// lanes. It echoes b_pass_lp (peel accept, for dt_pt) and b_more (MoreToDraw).
reg                    b_valid;
reg [RAS_LANES-1:0]    b_inside;
reg [31*RAS_LANES-1:0] b_invw;     // per-lane invW, sign-stripped
reg [4:0]              b_ox, b_oy;
reg [31:0]             b_tag;
reg [2:0]              b_mode;
reg                    b_zwdis;
reg                    b_peeling;   // carry the peel/opaque select into stage B
reg                    b_fwd;       // carry the FORWARD PT-resolve select into stage B
reg                    b_which;     // per-triangle is_pt (tri_is_pt) snapshot (PT => dt_pt=1)

// ---- peel + color tile buffers (own the RAM ports + access-pattern enforcement) ----
// per-lane resolved-bit slices for the forward PT compare (stage B chunk) and
// the PT_FIX walk chunk: pixel id = {y, x_hi} * LANES + lane.
// ---- pt_res as a 128x8 RAM (was a flat 1024-bit register) ----
// The old form needed, every cycle: a 1024:1 random read (blend), TWO 128:1
// 8-bit group reads (raster stage B, PT_FIX walk), a 1-bit write at an
// arbitrary index (1024-way decoder) and a whole-array clear - so it could
// not be memory and cost ~1k ALMs in muxing alone. Note the two group reads
// are 8-BIT ALIGNED, so the natural shape is 128 groups of 8.
// Three REPLICAS, each 1 dedicated read + 1 dedicated write, so no port ever
// conflicts; all take the same write. Each is 1024 bits.
// Read cursors follow the existing precedents exactly:
//   raster : presented at stage A ({ras_oy,ras_ox}) -> lands at stage B with
//            b_oy/b_ox, like the tile buffer's own chunk read
//   walk   : pb_rd, the read-AHEAD cursor - identical to u_zres's zr_raddr
//            (the old combinational form could use the pb_i write cursor)

// ================================================================
// control: front cnt (1..15) + tail pulse SR (d[1..16], parity alongside)
// ================================================================
reg        front;
reg [5:0]  cnt;
reg        cur_par;            // bank parity of the triangle in the FRONT phase
reg [16:1] d;                  // d[i] high during relative cnt 15+i
reg [16:1] dpar;               // that pulse's triangle bank parity
reg        rdy;

// retire tap + global lossless freeze on output backpressure
wire       stall = d[16] && !out_ready;
assign     in_ready = rdy && !stall;
wire       latch_now = in_valid && in_ready;
assign     busy = front || (|d);

// ================================================================
// ping-pong BANKED per-triangle results (write rel>=2, read <= rel 31)
// ================================================================
