    sub_setup(m0, k, x);
    if (!on) { sub_toggle(x, true, reg, val); m0.write(ch + reg, val); }   // start from the toggled state
    m0.write(ch + 0x00, m0.r(ch + 0x00) | 0x4000);
    m0.write(ch + 0x00, m0.r(ch + 0x00) | 0xC000);
