logic [31:0] pc;
logic [15:0] op;
form_e       form;
logic [2:0]  step;
logic        lane;        // issue lane of the instruction (0 = older in its issue cycle)
logic        rb;          // SR.MD & SR.RB at D (bank of R0-R7)
logic [2:0]  md;          // FPSCR FR / SZ / PR at D
