localparam int PMC_NMI        = 'h17;
localparam int PMC_TRAPA      = 'h18;
localparam int PMC_UBC_A      = 'h19;
localparam int PMC_UBC_B      = 'h1A;
localparam int PMC_IC_FILL    = 'h21;
localparam int PMC_OC_FILL    = 'h22;
localparam int PMC_ELAPSED    = 'h23;
localparam int PMC_FRZ_IC     = 'h24;
localparam int PMC_FRZ_OC     = 'h25;
localparam int PMC_FRZ_BR     = 'h27;
localparam int PMC_FRZ_REG    = 'h28;
localparam int PMC_FRZ_FPU    = 'h29;

  output pmc_ev_t     pmc_ev,
  output core_tap_t   tap
);
  // ============================================================================================================
  // architectural state of the CPU side (the FPU side lives in v1_fpu)
  logic [31:0] gpr [24];                       // R0-R7 bank 0, R0-R7 bank 1, R8-R15
  logic [31:0] sr, gbr, vbr, ssr, spc, sgr, dbr, pr;

  wire rb = sr[30] & sr[29];                   // MD & RB: which bank R0-R7 are
  wire rst_c = rst.cpu;                        // every reset kind implies the CPU reset (v1_soc_pkg rst_t)
  logic rst_q;                                 // rst_c last cycle: the first cycle of a reset loads the reset values

  // ============================================================================================================
  // pipeline latches
  uop_t ex [2], ma [2], sl [2];
  uop_t ex_res [2];                             // the EX latch with operands and EX results filled in
  uop_t ex_fin [2];                             // ex_res with the EX-stage checks (faults, UBC operand tags) applied
  logic fpu_idle;
  logic ex_smd [2];                             // SR.MD each EX micro-op was decoded with (dex.md; RTE slot: the new MD)

  // ============================================================================================================
  // fetch (v1_fetch, SOC.md 1.3.2 / 4.1; WI-CORE-B): the request `ifq` is acked in the request cycle on an IC hit (v1's
  // timing); a miss leaves the queue unfilled and D starves (hm 8.3: nothing freezes).  Every queue entry carries its
  // fetch fault, the UBC's fetch-side A / B tags and the redirect-target and delay-slot tags; the entries behind the
  // leader are pre-decoded for the P claim.  The fetch is held by pfz / mah / run = 0, asleep, and from an entry's
  // take cycle to its redirect (SOC.md 4.1 item 8: `hold`, and `hold_ma` for the MA unit's same-cycle answer, which
  // the fetch sees one cycle late); the take flushes it (`flush`), the entry's vector redirect is
  // `exc_redirect` (it waits for an outstanding uncached word / ITLB refill: `f_busy_wait`, counted in F).
  logic        q_v [3];
  logic [31:0] q_pc [2];
  logic [15:0] q_op [2];
  logic        q_tgt [2];
  logic [4:0]  q_tag [3];                      // {ubc_a, ubc_b, slot, fx != NONE, vec400} of q0 - q2
  fx_e         q_fxe [2];                      // the fetch fault of q0 / q1
  logic        f_q1_mem, f_q2_mem;             // (v1_fetch's frozen pre-decode outputs: w_mem[1], w_mem[2])
  logic [3:0]  f_w_mem;                        // the claim window (the queue + the word read this cycle): memory insn
  logic [2:0]  f_w_br;                         // ... a branch (the claim's scan stops after it)
  logic [15:0] f_w_op2, f_w_op3;               // ... the opcodes of positions 2 / 3
  logic [1:0]  pop;
  logic        redirect, rd_keep, rd_slot_pend, refetch;

// What the structure produces (s = the S cycle of the SR writer; ph = s mod 4, bce at ph 1 / 3, SOC.md 2.1):
//   * IMASK lowered in cycle s -> irq.req rises at s + 9 when s is even (ph 0 / 2), s + 10 when s is odd:
//       im_i s+1 | im1 at the first bce >= s+1 | im2, im3, R2 each 2 later | rq +1   =  9 or 10.
//     [HW] every warm acceptance on the console sits at exactly s + 9 or s + 10 in v1's issue schedule: core-integration
//     ci2 (12 cases: LDC SR 9, RTE 10, LDC SR ; k NOP ; BRA ; slot ; target 9 10 10 10 9 9 9 10 10 10), excint run 1 C1
//     (LDC SR 10, LDC.L SR 9, RTE 10), excint run 3 (RTE 10 x 8, LDC SR 9 x 8), and the excint2 PH sweep, where the
//     TCNT1 read fixes the phase: k = 7 when s - (the read's ack) is even, 8 when odd, in all 7 points not cut by an
//     instruction-cache line boundary (tb/v1_intc_tb.cpp replays all of them; the schedules are tb/v1_intc_progs.h,
//     which `make v1-intc-sched` re-derives from the current v1 core running the console ELFs).  The 0 / 6 values of
//     the PH sweep are cold-cache artefacts (k = the index of the first add on a new 32-byte line, or 0 when that line
//     is 1-4 adds away), not a phase of this path.  The PH pattern needs the Pclk read's ack at an even ph (v1_p4bus
//     P_D2 = 11: ack at pce + 11).
//   * BL is applied by the core at once (SOC.md 4.4.1): this path never looks at SR.BL for an ordinary interrupt
//     [HW PH BL 1->0: k = 0 in 24 of 24].
//   * an on-chip source rising in cycle e -> irq.req at e + 4 / 5 (R1 at the first bce >= e, R2, rq): the manual's
//     peripheral decision time "1 Icyc + 2 Bcyc" = 5 at I:B = 2:1 [M Table 19.7] is the slow phase.
//   * an NMI edge at the pin in cycle e -> irq.req (with BL = 0) at e + 8 / 9: n1 n2 n3 (the edge is seen when n2
//     differs from n3), nmi_pend, nmi_q, ns.  "1 Icyc + 4 Bcyc" = 9 [M].
//   * an IRL level change in cycle e -> irq.req at e + 14 / 15: irl1 irl2 h1 h2 (three equal samples), irl_f, R1, R2,
//     rq.  "1 Icyc + 7 Bcyc" = 15 [M]; a level that does not stay for three Bcyc samples is never seen [M 19.2.2].
//   * an IPR / ICR write, strobed in a pce cycle w -> R1 sees it at w + 2 (the next bce), irq.req at w + 6 [P].
//   * IMASK raised in cycle s (KOS irq_disable, an RTE or LDC SR back to IMASK 15) -> masked at once: irq.req (and
//     `wake`) = rq & (rl > im_i), so a request is gone from s + 1 (im_i holds the new mask from s + 1); the synchroniser
//     then drops rq itself at s + 9 / s + 10.  [HW] ci2 F nrec = 2 (the handler returns with SSR.IMASK 15 and TMU1
//     still pending: no re-take at the RTE target 3 cycles after RTE's S), ci2 irqloop budget_left = 9 (none after the
//     loop's final LDC SR raise), excint C1i (one record: none after the 0x180 handler resumes with IMASK 15); a raise
//     delayed like the lowering re-takes the request in each (SOC.md 3.4, I014).  No D boundary falls before s + 3
//     after an SR writer, so this equals a live compare, and the lockstep legality check is strict (SOC.md 6.2).
//   * `wake` (= the masked rq | ns) changes in the cycle after rq / ns are written: rq takes R2, which moves only at the
//     end of a bce cycle (ph 1 / 3), so `wake` rises in a ph-3 or ph-1 cycle (never right after a pce), 4 / 5 cycles
//     after an on-chip source (v1_cpg's RESYNC derives its 2-Pcyc wake cost from this edge; WI-CLK).  Asleep, IMASK
//     does not change, so the raise compare never moves this edge.
//   * irq.code follows the current winner while irq.req stays 1 (a higher source rising, or the winner dropping with a
//     lower one still above IMASK, changes the code with no gap in req); both leave through the same registers, so
//     code and req are always of one age.  The core latches the code at the take (SOC.md 3.4, 4.3.4 step 1), as
//     INTEVT is the winner at acceptance [M 19.4.1].

// ---- Line-fill buffer (caches-sq 3.2.1).  `f` is the fill on the bus: {entry, PA, critical quadword, beats received,
// quadwords written, the store's bytes (stbe / sd), st = a store allocated it (U <- 1 at completion), ld = the missing
// load waits for the critical beat}.  `fq` is one more line request queued behind it (loads and PREF only): a new load
// miss does not wait for the running fill [HW: a miss stream runs at the latency rate, "no read queue beyond one
// outstanding line"], and its request goes to the BIU once f's has been accepted.  A store miss or a MOVCA.L allocation
// needs the LFB itself: it waits until f and fq are both done [HW: a store-miss stream is LFB-bound].
//   claim     V[entry] <- 0 (a dirty victim is copied into the WBB first: the fill runs first, the write-back after
//             [HW]); a store miss puts its bytes into the LFB (U <- 1 at completion)
//   rd_v      the beat (critical quadword first, then wrap [HW q2 q3 q0 q1]) is captured into `fb`; the missing load
//             takes it from there in rd_v + 1 (C6)
//   rd_v + 1  the merge stage: fb under the store's bytes -> `fw` [HW: stored bytes survive the fill]
//   rd_v + 2  `fw` is written into the data RAM (the port is busy) and the quadword is marked written: a load to the
//             filling line reads it from rd_v + 3 [HW `ldw`: a second load to beat k of a filling line costs +1 +2k
//             over its hit, i.e. beat k at unfreeze + 2 + 2k]
//   W3 + 1    completion stage (after the last beat's write): tag <- PA[28:10], V <- 1, U <- st; f <- fq.  So a store
//             to the filling line (which waits for the whole line) hits at W3 + 2 = r + 22, and the next LFB claimant
//             allocates there [HW: stst / ldst +22, store-miss stream 22.15 per line, "fill complete ~24 after the
//             store's MA"].
//   OCI       a flash clear while f / fq are in flight: every in-flight fill belongs to an access already acked (the
//             CCR write is itself an MA access, after them in program order), which the lockstep model applied at its
//             ack; the OCI then invalidated the line there.  So the fill is `kill`ed: it completes (beats, data RAM)
//             and writes the tag, but not V or U, and serves no later lookup (a killed fill is not "the line being
//             filled": the access waits for the entry's fill to complete and then misses) [P: program order, as
//             tb/sh4_cache.h; unmeasured].  A line request claimed in the OCI's own cycle is younger: not killed.
//   The kern.S loops these rules produce on the stub (per iteration, console - 0.17 fixed cost in brackets): stld 22
//   (22.06), stst / ldst 26 (26.08), prefld d = 1..5 20 (20.25), d = 6 / 7 / 8 24 / 26 / 29 (24.12 / 26.06 / 29.03),
//   stldgap g <= 7 26, g = 8 29 (26.09 / 29.00), ldw 20 22 22 24 24 26 26 (+0.23 each, as the chain's refresh share).
// ---- Write-back buffer (caches-sq 3.2.2): one line {PA[28:5], 32 bytes}; loaded by a dirty victim (load / store / PREF
// miss, MOVCA.L allocate), a dirty OCBP / OCBWB, and an address-array write that cleans or invalidates a dirty line;
// its BZ_LINE write goes out after the fill (the BIU's order: a fill before its write-back; a read of the WBB's line
// waits for it).  An operation that needs it while it is full waits until its `done` [HW: isolated dirty OCBP / OCBWB
// cost 0, back to back 12.2 per line = the write tenure].
// ---- Write-through buffer (caches-sq 3.2.3): one entry {PA, size, lane data, lane byte enables}, no merging; every
// write-through or uncached store (MOVCA.L included) and TAS.B's write.  Freed at its `done` [HW: 10.1 per store back
// to back = the single-write tenure].  Every read request of the OC (fill, uncached read) waits until it is empty [HW:
// an uncached load waits for the WTB; P2 store -> load 28.3 per pair].

// ================================================================================================================
// state
logic [18:0]   tag [NL];
logic [NL-1:0] vld, dty;                       // V, U
logic [63:0]   dat [NL][4];

typedef struct packed {                        // the fill on the bus (the LFB)
  logic        v;
  logic [8:0]  idx;
  logic [28:5] pa;
  logic [1:0]  crit;
  logic        acc;                            // the BIU has accepted the line request
  logic [2:0]  nb;                             // beats received
  logic        crit_seen;
  logic        crit_dlv;                       // the critical word has been delivered (the cycle after its rd_v
                                               // has passed): ends the 0x22 tenure
  logic [3:0]  arrived;                        // quadwords written into the data RAM
  logic        st;                             // a store allocated it: U <- 1 at completion
  logic        ld;                             // the missing load waits for the critical beat
  logic        cmp;                            // every beat written: the completion stage is this cycle
  logic        kill;                           // an OCI after its access: complete without V / U, serve no lookup
  logic [31:0] stbe;                           // the store's bytes (per byte of the line)
} fill_t;
typedef struct packed {                        // the line request queued behind it (loads and PREF)
  logic        v;
  logic [8:0]  idx;
  logic [28:5] pa;
  logic [1:0]  crit;
  logic        acc;
  logic        ld;
  logic        kill;
} fillq_t;
fill_t       f, f_n;
fillq_t      fq, fq_n;
typedef enum logic [1:0] { FS_NONE, FS_F, FS_FQ, FS_NEW } fsel_e;
fsel_e       fsel;                             // which line request is on bq_fill this cycle
logic [63:0] sd [4];                           // the store's data in the LFB (bytes under f.stbe)

// The block is the arithmetic unit of Hitachi US 6,038,582 (FIG. 4 / 29 / 34): four Booth multipliers FM0..FM3,
// one aligner per product, a four-input adder and one normalise/positive/round circuit.  FIPR uses it once;
// FSCA and FSRRA sequence it (4 and 3 multiply steps) through feedback paths from the product registers to the
// multiplier input latches, with a coefficient ROM in place of the register file.  Widths below are the ones
// pinned by the bit-exact FIPR model (model/fipr/fipr_ref.h) and the FSCA/FSRRA structural models
// (model/fsca/sh4_fsca.h, model/fsrra/fsrra_ref.h; shareable C for all of it: model/sh4_fpu_approx.h).
package fpu_vec_pkg;
  // ---- datapath widths -------------------------------------------------------------------------------------
  localparam int RECW  = 28;   // Booth-recoded operand (port B): two's complement, 14 radix-4 digits over bits -1..27.
                               // FIPR presents the 24-bit FVn mantissa zero-extended; FSCA/FSRRA feed back signed values.
  localparam int MULW  = 25;   // multiplicand (port A): two's complement; FIPR = {1'b0, FVm mantissa}; FSCA dx is signed.
  localparam int RAWW  = 56;   // truncated row sum of the array (always a multiple of 2^16)
  localparam int PRODW = 29;   // product register M[n] = (raw + 2^19) >>> 20 : 28 bits + sign
  localparam int ALNW  = 32;   // aligner output / adder input
  localparam int SUMW  = 35;   // four-input adder result

  localparam logic [RAWW-1:0] ROUND_K = 56'd1 << 19;   // the rounding constant every product gets before >> 20

  // ---- opcodes --------------------------------------------------------------------------------------------
  typedef enum logic [1:0] { OP_FIPR = 2'd0, OP_FSCA = 2'd1, OP_FSRRA = 2'd2 } op_e;

  // ---- multiplier input-latch sources (the selectors 302..312 of FIG. 29, generalised) ----------------------
  // Port A (multiplicand) sources
  typedef enum logic [2:0] {
    A_HOLD = 3'd0,   // keep the latch ("value is held by restricting updating of input latch")
    A_OPA  = 3'd1,   // FIPR operand mantissa
    A_DX   = 3'd2,   // the offset dx from the sign expander
    A_TAB  = 3'd3,   // a table value (FSCA: sine field S of the addressed entry)
    A_FB   = 3'd4    // feedback: product register M[fb_src] >>> fb_sh
  } asel_e;
  // Port B (Booth-recoded) sources
  typedef enum logic [2:0] {
    B_HOLD = 3'd0,
    B_OPB  = 3'd1,   // FIPR operand mantissa
    B_DX   = 3'd2,   // dx (FSRRA cubic final product recodes dx)
    B_CONST= 3'd3,   // a stored coefficient (KC, C1F, C3<<5, REC1..3)
    B_FB   = 3'd4    // feedback: M[fb_src] >>> fb_sh
  } bsel_e;

  logic        sx_w;         // writer: SSR SPC DBR VBR GBR Rn_BANK S PR (incl. BSR / JSR / BSRF)
  logic        sx_r;         // reader: STC*, STS PR*, RTS, RTE, CLRS, SETS, @(R0,GBR) ops, @(disp,GBR) MOVs
  // FPU
  logic        fpu_dec;      // decoded by the FPU (reads the FPSCR mode): FE group, FP moves, LDS / STS FPSCR
  logic        fe;           // FE group: held while the multiplier's busy count is > 2, and by the divider's
                             // FE-issue inhibit (the cycle before each of its result passes)
  logic        fe_arith;     // FE arithmetic (FADD..FTRC, FCMP, FDIV, FSQRT, doubles): held by the set_fe hold
  logic        arr;          // multiplier-array class (FIPR FTRV FSCA FSRRA, MUL/DMUL/MAC, CLRMAC, LDS MACx,
                             // FRCHG, FSCHG): held by the set_arr hold
  logic        rf_rd;        // FR operands read from the register file only (vector ops, doubles)
  ukind_e      fpul_rd;
  logic [2:0]  fw_width;     // destination width in words (1, 2, 4): position of a word = index % width
  logic [3:0][4:0] f_rd;     // per destination position: to bypass readers (FE ops, FP moves)
  logic [3:0][4:0] f_st;     //   to FP store data (the late capture of the FE result bus)
  logic [3:0][4:0] f_rf;     //   to register-file readers = FS, the word's register-file write
  logic [3:0][4:0] f_wr;     //   to a later writer of the word (write order)
  logic [1:0]  f_war;        // 2: a later writer of one of this instruction's source words waits a cycle (the
                             // sources are read in F1)
  logic [4:0]  u_rd, u_st, u_sts, u_rf, u_wr;   // FPUL result by reader kind (D, store, STS FPUL,Rn, RF) / WAW
  logic [4:0]  lat_fpscr_c;  // FPSCR cause / flags to LDS / STS FPSCR (0: not written): written a cycle after the
                             // last FS
  logic [2:0]  lat_fpscr_m;  // FPSCR mode (FR / SZ / PR) to every FPU-decoded instruction (0: not written)
  logic        rd_fpscr_c;   // LDS / LDS.L / STS / STS.L FPSCR
  // integer multiplier / MACH:MACL (one busy counter; the multiplier is the FPU's array)
  logic [2:0]  lat_mac;      // 6 multiply, 5 CLRMAC / LDS MACx (0: not a MAC writer)
  logic [1:0]  mac_rd;       // 1 STS MACx,Rn (may issue at busy <= 2), 2 STS.L MACx (busy <= 1)
  // FPU dispatch holds this instruction sets (issue distances; 0 = none)
  logic [4:0]  set_arr;      // array class may issue at this distance (the vector sequencer's passes)
  logic [4:0]  set_fe;       // FE arithmetic may issue at this distance: one pass longer after a vector op, whose
                             // last pass shares the FE adder / FS write port
  logic [4:0]  set_div;      // the divider's release: next FDIV / FSQRT.  Its result passes come the cycle(s)
                             // before (one; two for PR = 1, lower word first) on the divider's own result path
  logic        ftrv;         // FTRV: group lock and XMTRX anti-dependency
  logic        fp_ls;        // an LS-pipe FP access (FP moves / loads / stores / FLDS / FSTS / FABS / FNEG)
} tc_t;

logic [1:0] h;
exc0_s = 1'b0;
for (int l = 0; l < 2; l++) if (sl[l].v && sl[l].uk == UK_EXC0 && !ksl[l] && !frz) exc0_s = 1'b1;
ubc_dq   = s_dq;
sr_imask = sr_rd[7:4];                                     // architectural SR with the S-stage write-through
sr_bl    = sr_rd[28];
asleep   = sleep_issued;
sleep_req = sleep_issued && pipe_empty && !itake && run && run_q;
irq_ack = exc0_s && ent_intr && !ent_nmi;
nmi_ack = exc0_s && ent_intr && ent_nmi;
// the entry's writes outside the CPU (SOC.md 3.4): EXPEVT (INTEVT for an interrupt), TRA, TEA / PTEH.VPN, at
// EXC0's S; a multiple hit writes TEA / PTEH only, at its take, with the reset request
excw = '0;
if (exc0_s && ent_rst == 2'd0)
  excw = '{v: 1'b1, intr: ent_intr, code: ent_code, tra_v: ent_tra_v, tra: ent_tra, tea_v: ent_tea_v, tea: ent_tea,
           ubrk: ent_ubrk};
cpu_rst_req = exc0_s && ent_rst == 2'd1;
mhit_req = exc0_s && ent_rst == 2'd2;
if (mhit_req) excw = '{v: 1'b0, intr: 1'b0, code: EXP_MHIT, tra_v: 1'b0, tra: '0, tea_v: 1'b1, tea: ent_tea, ubrk: 1'b0};
// UBC condition-match flags: a tagged instruction reached its break point, taken or not (debug-ubc-hudi 4.3).  A
// break that is taken sets its flags when its entry commits (EXC0's S): an older break taken meanwhile kills it and
// its flags are never set [HW AB_sameSPC: A post on i, B pre on i + 1 -> CMFA only].  A tag that does not break
// (SR.BL = 1, SEQ's A half, a B match with channel B not live) sets them where it is reached: a pre-execution tag
// when its instruction issues, a post / operand tag when its micro-op leaves MA, a data match at S.
ubc_hit = '0;
h = 2'b00;
if (!frz) begin
  if (exc0_s) h = ent_hit;
  if (iss0) h = h | tg_pre[0];                             // pre tags that did not break (BL = 1, SEQ's A half)
  if (iss1) h = h | tg_pre[1];
  for (int l = 0; l < 2; l++)                              // post / operand tags leaving MA without a take
    if (ma[l].v && ma[l].uk == UK_NORM && ma[l].fx == FX_NONE && !kma[l] && !(matake && ma_tk[l]))
      h = h | ma_hit[l];
  if (!stake && !sdef_c) h = h | s_brk_hit;                // a data match that did not break
  ubc_hit = '{hit_a: h[1], hit_b: h[0]};

//  * Classes (Section 10 data_type_of): exponent all ones, fraction 0 -> infinity; fraction != 0 -> NaN, SIGNALING when
//    the fraction MSB is 1 (bit 22 / bit 51: the SH-4 convention, the opposite of IEEE 754-2008).  Exponent 0: a zero,
//    and with DN = 1 a denormal too (also for FCMP, FTRC and the conversions); with DN = 0 a denormal is a nonzero
//    number that no scalar operation computes with: it is the FPU error E or a special case (below) in every
//    function, FCMP compares its bits and FTRC truncates it to 0 -- so unpack() only classifies it.
//  * NaN results (Section 6.2.2): every NaN produced is the SH-4 qNaN 0x7FBFFFFF / 0x7FF7FFFF_FFFFFFFF (input
//    payloads are never propagated).  V is raised for an sNaN input and for the invalid operations (inf - inf,
//    0 * inf, 0 / 0, inf / inf, sqrt(< 0)); a qNaN input alone raises nothing.
//  * Rounding (Section 6.4): RN = nearest-even, RZ = truncate.  Overflow: O and I, result +-inf (RN) or +-max
//    finite (RZ) with the sign of the unrounded value (6.5).
//  * Underflow: the result is rounded ONCE on the denormal grid (below the minimum normal the significand is shifted
//    right to the minimum exponent, the shifted-out bits joining the sticky, and rounded at the same positions).
//    DN = 0: that is the result (gradual underflow), I when inexact, U when inexact and the rounded result is below
//    the minimum normal ("tiny after rounding on the grid": [HW fpdn part 2] 36,864 DN = 0 values; tiny-before-
//    rounding or IEEE's after-rounding rule mismatch 2,086 / 534 records).  DN = 1: a result below the minimum normal
//    is the zero of its sign with U | I (check_single_exception); in RN an exact value in [2^-126 - 2^-150, 2^-126)
//    rounds UP to the minimum normal (I only, no U), RZ flushes everything below 2^-126 [HW fpdn: the DN = 1 records
//    agree].  An exact zero raises nothing.
//  * FPU error E (DN = 0 only; pm 6.5; [HW fpdn]): the functions report e = 1 when the instruction takes the FPU-error
//    trap -- a denormal operand reaching the arithmetic, after the NaN and invalid-operation checks: sNaN (V) and, in
//    single precision, any NaN win; FDIV x / 0 is Z (a denormal x is nonzero); FMAC 0 * inf and (inf product) - inf
//    are V first; FSQRT of a negative denormal is V.  FTRC, FCMP and FLOAT never raise E (pm 10 lists E for FTRC: the
//    console does not raise it).  With e = 1 the result and cause are meaningless (the core traps: destination not
//    written, cause = E alone, flags unchanged -- v1_fpu).
//  * Doubles with DN = 0 [HW fpdn part 3]: the special-case logic classifies a double from its HIGH word: a NaN with a
//    fraction bit in the high word beats E, a denormal with one there raises E early; the low word only turns a
//    high-word zero into a denormal and a high-word infinity into a NaN, one step later in each operation's priority
//    order (fadd_x, fmul_x, fdiv_spec).  [HW] examples: FMUL.D 0x00000000_00000001 x inf = inf (no E, no V); FDIV.D
//    0x00000000_00000001 / 0 = +0 with no cause; FADD.D 0x7FF00000_00000001 + denormal = E, 0x7FF40000_00000000 +
//    denormal = qNaN.
//  * Zero signs are IEEE (RN / RZ): x + (-x) = +0, (+0) + (-0) = +0, (-0) + (-0) = -0; FMAC likewise on the exact
//    product.  (The manual's FMAC pseudo-code writes zero(n, s0^sm^sn) for 0*x + 0, contradicting its own special-case
//    table; the table is IEEE, which the console confirms on the part 1 FMAC rows.)
//  * FMAC = one rounding of the exact a*b + c.  NaN priority per the FMAC pseudo-code: any sNaN -> V; a or b qNaN ->
//    qNaN; 0 * inf -> V even when c is a qNaN; c qNaN -> qNaN; (+-inf product) + (-+inf) -> V; then E.

  mt_e        mt;
  logic [5:0] np;                              // pieces
  logic [3:0] pb;                              // bytes per piece
  logic [5:0] grp;                             // pieces per group (a T1 each group)
  logic [3:0] pre, s0, post;
  logic [6:0] wf;                              // waits before the first piece of a group (PCMCIA: up to 15 + 50)
  logic [5:0] wn;                              // waits before a later piece of a group
  logic       rf, rn;                          // RDY# sampled on the first / a later piece
} bp_t;

/* verilator lint_off UNUSEDSIGNAL */          // whole records: the plan and the length read the fields they need
function automatic bp_t bplan(input bx_t x);
  bp_t        p;
  logic [2:0] area, c;
  logic [3:0] wb, sb;
  logic [5:0] w;
  area = x.addr[28:26];
  p    = '0;
  p.mt = area_mt(regs, area);
  wb   = wid_bytes(area_wid(regs, area));
  sb   = x.size == BZ_LINE ? 4'd8 : sz_bytes(x.size);
  p.pb = sb < wb ? sb : wb;
  p.np = x.size == BZ_LINE ? 6'd32 / {2'd0, p.pb} : (sb > wb ? {2'd0, sb} / {2'd0, wb} : 6'd1);
  c    = aw_code(regs, area);
  p.grp = 6'd1;
  unique case (p.mt)
    MT_DRAM: begin
      p.grp  = p.np;
      p.wf   = {5'd0, regs.mcr[17:16]} + 7'd1;                              // RCD {2..5} - 1
      unique case (c)                                                       // CAS width {1 2 3 4 7 10 13 16} - 1
        3'd4:    w = 6'd6;
        3'd5:    w = 6'd9;
        3'd6:    w = 6'd12;
        3'd7:    w = 6'd15;
        default: w = {3'd0, c};

// ---- building a micro-op in D
/* verilator lint_off UNUSEDSIGNAL */       // the function reads the fields its forms need
function automatic uop_t mk_uop(input logic [31:0] pc, input logic [15:0] op, input dec_t dd, input ictl_t cc,
                                input logic [2:0] step, input logic lane, input logic [2:0] md,
                                input logic [7:0] isn, input logic slot, input logic [31:0] cont);
  uop_t u;
  logic [4:0] pm, pn;
  u = '0;
  u.v = 1'b1; u.pc = pc; u.op = op; u.form = dd.form; u.step = step; u.lane = lane; u.rb = rb; u.md = md;
  u.isn = isn; u.slot = slot;
  // ftea: until EX finds a fault (then the faulting address) the instruction after this one in program order --
  // the SPC of a completion-type break on it (UBC post-execution / operand-address, the data break's group)
  u.ftea = cont;
  u.trap = cc.form_x == XF_TRAPA && step == 3'd0;
  pm = gphys(op[7:4], rb);
  pn = gphys(op[11:8], rb);
  u.pa = pm; u.pb = pn; u.pc0 = gphys(4'd0, rb);
  u.a = gpr_rd[pm]; u.b = gpr_rd[pn]; u.c = gpr_rd[u.pc0];
  u.tin = t_now; u.qin = q_now; u.min = m_now; u.sin = s_now;
  // system register read (STC / STS / RTS / RTE / GBR-relative)
  unique case (dd.form)
    F_STC_SR_RN, F_STC_L_SR_AT_PRE_RN: u.cr = {sr_rd[31:10], m_now, q_now, sr_rd[7:2], s_now, t_now};
    F_STC_GBR_RN, F_STC_L_GBR_AT_PRE_RN, F_MOV_B_AT_D_GBR_R0, F_MOV_W_AT_D_GBR_R0, F_MOV_L_AT_D_GBR_R0,
    F_MOV_B_R0_AT_D_GBR, F_MOV_W_R0_AT_D_GBR, F_MOV_L_R0_AT_D_GBR, F_TST_B_IMM_AT_R0_GBR, F_AND_B_IMM_AT_R0_GBR,
    F_OR_B_IMM_AT_R0_GBR, F_XOR_B_IMM_AT_R0_GBR: u.cr = gbr_rd;
    F_STC_VBR_RN, F_STC_L_VBR_AT_PRE_RN: u.cr = vbr_rd;
    F_STC_SSR_RN, F_STC_L_SSR_AT_PRE_RN: u.cr = ssr_rd;
    F_STC_SPC_RN, F_STC_L_SPC_AT_PRE_RN: u.cr = spc_rd;
    F_STC_SGR_RN, F_STC_L_SGR_AT_PRE_RN: u.cr = sgr_rd;
    F_STC_DBR_RN, F_STC_L_DBR_AT_PRE_RN: u.cr = dbr_rd;
    F_STC_RM_BANK_RN, F_STC_L_RM_BANK_AT_PRE_RN: u.cr = gpr_rd[gbank(op[6:4], rb)];
    F_STS_PR_RN, F_STS_L_PR_AT_PRE_RN, F_RTS: u.cr = pr_rd;
    F_RTE: u.cr = ssr_rd;
    default: u.cr = '0;

// ---- state -----------------------------------------------------------------------------------------------------
logic [11:0] frqcr;                     // FRQCR[11:0] (15:12 read 0)
logic [7:0]  stbcr;
logic        dslp;                      // STBCR2[7]
logic [3:0]  bdiv;                      // active Bclk divider (Icyc per Bclk period; pcnt reloads at pce only)
logic [2:0]  pcnt, bcnt;                // enable down counters
logic [11:0] dv;                        // WDT divider
st_e         st;
logic [3:0]  rs;                        // RESYNC: pce edges still to wait
logic [3:0]  es;                        // ENTRY: pce edges still to wait
logic        ck_on;                     // the RESYNC in progress began in ENTRY: the CPU clock never stopped
logic [1:0]  sp;                        // SETTLE: WDT overflows still to wait
logic        deep;                      // the sleep in progress is a deep sleep (DMAC stopped until RUN)
logic        sleep_q;                   // sleep_req as sampled in RUN (edge detector)
logic        sleep_pend;                // a sleep_req edge that met a relocking FRQCR write: taken after the settle
logic        sbx;                       // the settle / resync in progress ends a standby (STATUS normal in RESYNC)

wire clk_run    = st != S_STANDBY && st != S_SETTLE;
wire pce_now    = clk_run && pcnt == 3'd0;
wire sleep_edge = sleep_req && !sleep_q;           // used in RUN only

assign ce.pce     = pce_now;
assign ce.bce     = clk_run && (bcnt == 3'd0 || pcnt == 3'd0);
assign div        = dv;
assign ratio_inc  = ratio_of(frqcr[5:3]);
assign cpu_run    = st == S_RUN;
assign cpu_clk    = st == S_RUN || st == S_ENTRY || (st == S_RESYNC && ck_on);
assign dmac_run   = !(deep || st == S_STANDBY || st == S_SETTLE) && !stbcr[4];
assign stby       = st == S_STANDBY;
assign mstp       = stbcr[4:0];
assign wdt_settle = st == S_SETTLE;
always_comb begin                       // STATUS1-0 (hm 9.7): HH reset, HL sleep, LH standby, LL normal
  if (rst.por || rst.man)                                        status = STS_RESET;
  else if (st == S_SLEEP || st == S_DSLEEP || (st == S_RESYNC && !sbx)) status = STS_SLEEP;
  else if (st == S_STANDBY || st == S_SETTLE)                    status = STS_STANDBY;
  else                                                           status = STS_NORMAL;

// FPU exceptions (SOC.md 4.3.2 / 4.3.8, core-integration 3.5.5, exceptions-intc 3.8).  No new issue comparator.
// Trap effects (SOC.md 4.3.8) [HW tools/hw/fpdn: FSQRT(1.5) + EN.I leaves 0x00001084, FMUL.D max x 1.5 + EN.I
// 0x00085094, an exact FADD + EN.I 0x00040080, sNaN + EN.V 0x00050840]: the destination is never written; FPSCR's
// cause and flags are what the untrapped execution writes -- cause <- the computed {V, Z, O, U, I}, flags |= them --
// except for an E trap, whose cause is E alone with the flags unchanged.
//   * `trap_d`: decided at D from the opcode and the enables: an enabled O / U / I that the instruction can raise, and
//     FTRV's V [HW model/timing, exceptions-intc run 1]; plus FCMP DR's V, from its register-file operands [P: FCMP DR
//     reads the register file only, so its operands at D are its F1 operands; its compare pass is a sequencer step
//     with no EX micro-op to convert].  The core issues EXC0 instead of the instruction; the instruction still
//     dispatches here as a trap pass (di_v with trap_d), which is the instruction's own execution with its
//     destination cleared: it computes the operation on the path an untrapped one takes and writes only the cause.
//     A single FE op's pass computes at F1 (bypassed operands) and writes the cause at FS; a double's (and FCMP DR's)
//     cause is computed at D from the register file (the double sequencer's value functions) and rides one F1 F2 FS
//     pass; FDIV / FSQRT (single and DR) run the recurrence -- the divider record and its result pass(es), the double
//     sequencer's setup passes for DR -- and the result pass writes the cause (so a trap pass occupies the divider as
//     the untrapped divide does [P: the handler's first FDIV / STS FPSCR after a trapped FDIV issues when it would
//     after the same FDIV untrapped; not measured]); a vector trap pass runs its array passes, its results write the
//     cause (model/fipr, model/fsca, model/fsrra: "the destination is left unchanged while cause and flag are still
//     updated", measured).  Every trap pass holds the FPSCR readers (LDS / STS FPSCR: fscr_busy) until its cause is
//     written, like any cause writer.
//   * `trap_f1`: V / Z / E on the operands, checked where the instruction first is in F1 (the cycle after issue):
//     single FE ops on the bypassed operands [HW ci2: a sNaN loaded by the FMOV.S right before FADD traps as fast as
//     one from the register file]; doubles and the vector ops (FIPR V, FSRRA V / Z) on the register-file operands they
//     read at D, registered with their record.  E (FPSCR.DN = 0, a denormal operand, never masked) as the console
//     raises it [HW tools/hw/fpdn, SOC.md 9.17; WI-FPDN]: the value functions' `e` (v1_fp_pkg: FADD FSUB FMUL FMAC
//     FCNVSD FCNVDS, after their NaN / invalid checks; FTRC and FCMP never), fdiv_spec's for FDIV / FSQRT, and the
//     vector unit's st_e for FSRRA.  DN = 0 reaches every value function, the divider and the vector unit (`dn0`).
//     The core converts the instruction's own micro-op (in EX) into EXC0 in place and kills
//     everything younger; this FPU then drops the trapping instruction's own work (a killed kill_incl = 0 kill naming
//     trap_f1_isn is the taken trap) and writes its cause in the take cycle: the operation's computed cause, which
//     for a V / Z trap is V / Z alone (an invalid operation's qNaN and a division by zero's infinity are exact), or E
//     alone; a vector op runs on without a destination and writes its cause at its results.
// The trapping instruction keeps its cause tag and writes its cause at the trap; an older completion that lands
// later only ORs its flags [HW ci2: FDIV 1/3 in flight, younger FADD V trap -> 0x00050844, FR9 = 0x3EAAAAAB].

  /* verilator lint_off UNUSEDSIGNAL */          // rst.pin / man / cpu (pin implies por; the others hold the IC)
  input  rst_t        rst,
  input  ireq_t       ifq,                       // md: the privilege checks are v1_mmu's / v1_fetch's
  /* verilator lint_on UNUSEDSIGNAL */
  input  logic        if_hit,
  /* verilator lint_off UNUSEDSIGNAL */
  input  logic [28:0] if_pa,                     // [1:0]: the fetch is word aligned
  /* verilator lint_on UNUSEDSIGNAL */
  input  logic        if_c,
  input  fx_e         if_fx,
  input  logic        if_vec400, if_stall,
  output irsp_t       ifr,
  /* verilator lint_off UNUSEDSIGNAL */          // off[27:13] / off[1:0] (the block, a longword view), dma
  input  p4s_req_t    pq_arr,
  /* verilator lint_on UNUSEDSIGNAL */
  output p4s_rsp_t    pr_arr,
  input  logic        arr_strobe,
  /* verilator lint_off UNUSEDSIGNAL */          // the OC fields of ccr_t
  input  ccr_t        ccr,
  /* verilator lint_on UNUSEDSIGNAL */
  input  logic        ici,
  output logic        xl_req, xl_itlb,
  output logic [31:0] xl_va,
  /* verilator lint_off UNUSEDSIGNAL */          // xl_mhit: the multiple-hit reset is v1_mmu's (arr_mhit); xl_pa[9:0]
  input  logic        xl_hit, xl_mhit, xl_stall,
  input  logic [28:0] xl_pa,
  /* verilator lint_on UNUSEDSIGNAL */
  output bq_t         bq_fill, bq_unc,
  /* verilator lint_off UNUSEDSIGNAL */          // read-only requester: no write strobes; rd_last / done by count
  input  bs_t         bs_fill, bs_unc,
  /* verilator lint_on UNUSEDSIGNAL */
  output commit_rec_t [CT_IC_N-1:0] tap,
  output pmc_ev_t     pmc_ev
);
  localparam int NL = 256;

//   D1 = 0   the strobe is in the acceptance cycle, from the incoming request (Iclk: no clock crossing)
//   D1 > 0   the strobe is the first cen cycle at least D1 cycles after the acceptance (the request register and
//            D1 - 1 more synchroniser stages), once the previous bus cycle is over
//   D2       read data: ack D2 cycles after the last transfer (a valid bit through D2 flops; the data waits in one
//            capture register, as in a handshake synchroniser)
//   WREL     posted write: the path-side "taken" flag is set at the first cen edge after the capture; the entry is
//            released at the end of the WREL-th cycle after that edge
//   POSTED   the CPU's (master 0's) writes ack from its front end (not here) and drain from the slot; a bus cycle
//            lasts its transfers + one recovery cen cycle.  Every other write (every write on a path without POSTED,
//            and the DMAC's on any path) acks in its capture cycle and frees the slot then (SOC.md 3.1.1)
//   HALF16   a longword occupies the bus for a second transfer, the next cen cycle after the capture
//   LAND     a write lands at its slave at the end of its bus cycle (SOC.md 9.19, closed at M1a): the address strobe
//            (st_v, which times the bus cycle, the entry release and the read return exactly as without LAND) does
//            not reach the slave for a write; the write is presented to its slave (sl_v / sl_q) in the first cen cycle
//            after its strobe in which the bus-cycle counter is 0 again, i.e. its transfers + 1 path clocks after the
//            strobe (a Pclk byte / word 8 Icyc, a longword 12), the cen cycle in which the path's next strobe may go.
//            A read whose strobe falls in a landing cycle is presented to its slave one cen later (the landing write
//            first, so the read returns the new value); its data waits in the capture register and its ack keeps the
//            strobe's schedule (D2 = 11 > one Pcyc: the p4b w16_r16 brackets 24 / 27 / 26 / 25 do not move) -- unless
//            that cen comes later than the schedule: v1_cpg withholds pce while it settles after a PLL-relocking FRQCR
//            write, which lands in exactly such a cycle.  The ack then waits for the capture (rhold: the schedule
//            has run out, rdf still pending) and goes in the cycle after it (M1a-verify F2: the FRQCR read behind a
//            relocking write returned the old value, and its slave never saw it).  A non-posted (DMAC) write is acked
//            at its landing and holds the slot until then (the slave has applied it when the DMAC consumes the ack,
//            SOC.md 3.1.1).  A strobed write lands
//            whatever reset follows (SOC.md 3.1.6: a strobed transaction completes); only a power-on reset drops it.
//            The slave must not stall (no Pclk slave does)
module v1_p4bus_path import v1_soc_pkg::*; #(
  parameter int D1 = 1,
  parameter int D2 = 6,
  parameter int WREL = 2,
  parameter bit POSTED = 1'b1,
  parameter bit HALF16 = 1'b0,
  parameter bit LAND = 1'b0

// Additions to the ARCH.md contract (appended to the enum, existing encodings unchanged):
//   A_TAS  TAS.B's modify step: b = the loaded byte (zero-extended), r = b | 0x80, T = (b[7:0] == 0).
//          (AND.B / OR.B / XOR.B / TST.B #imm,@(R0,GBR) are A_AND / A_OR / A_XOR / A_TST with a = imm, b = byte.)
package v1_alu_pkg;
  typedef enum logic [5:0] { A_ADD, A_ADDC, A_ADDV, A_SUB, A_SUBC, A_SUBV, A_NEG, A_NEGC, A_AND, A_OR, A_XOR, A_NOT,
    A_TST, A_CMPEQ, A_CMPHS, A_CMPGE, A_CMPHI, A_CMPGT, A_CMPPZ, A_CMPPL, A_CMPSTR, A_DIV0S, A_DIV0U, A_DIV1, A_DT,
    A_EXTSB, A_EXTSW, A_EXTUB, A_EXTUW, A_SWAPB, A_SWAPW, A_XTRCT, A_MOV, A_MOVT, A_ROTL, A_ROTR, A_ROTCL, A_ROTCR,
    A_SHAL, A_SHAR, A_SHLL, A_SHLR, A_SHLL2, A_SHLR2, A_SHLL8, A_SHLR8, A_SHLL16, A_SHLR16, A_SHAD, A_SHLD,
    A_CLRT, A_SETT,
    A_TAS } alu_op_e;
  typedef struct packed { logic [31:0] r; logic t, q, m; logic wr_t, wr_qm; } alu_out_t;

  // a = Rm-side operand (or the immediate, sign- or zero-extended by the caller), b = Rn-side operand
  function automatic alu_out_t v1_alu(input alu_op_e op, input logic [31:0] a, input logic [31:0] b,
                                      input logic t, input logic q, input logic m);
    alu_out_t    o;
    // ---- adder ---------------------------------------------------------------------------------------------
    logic [31:0] x, y;          // adder inputs (y already inverted for a subtraction)
    logic        cin;
    logic [32:0] sum;           // {C, S}
    logic        c, v, z;
    logic        sub1;          // DIV1: this step subtracts the divisor (old Q == M)
    logic        q1;            // DIV1: the new Q
    // ---- logic unit / shifter / misc ----------------------------------------------------------------------
    logic [31:0] lu;
    logic [31:0] hi, lo;
    logic [5:0]  s;
    logic [63:0] fun;
    logic [31:0] misc;
    logic        sh_t;          // the bit a 1-bit shift / rotate moves out (T)
    // ---- result bus ----------------------------------------------------------------------------------------
    logic [1:0]  cls;           // 0 adder, 1 logic, 2 shifter, 3 misc
    logic [31:0] res;
    logic        wr_r;

// a refresh / mode command / PALL: no data bus, so rel_d and the idle rule's record stay; only an SDRAM read's
// overlap with the next read or write ends (the two are no longer consecutive)
if (rf_go)    begin rn = brel(blen_t'(rf_len)) - brel_t'(1);   rec.sd_rd <= 1'b0; rec.sd_ln <= 1'b0; end
if (md_go)    begin rn = brel(blen_t'(md_len)) - brel_t'(1);   rec.sd_rd <= 1'b0; rec.sd_ln <= 1'b0; end
if (pall_go)  begin rn = brel(blen_t'(pall_len)) - brel_t'(1); rec.sd_rd <= 1'b0; rec.sd_ln <= 1'b0; end
if (ddt_bavl) begin rn = brel_t'(1); rdn = brel_t'(1);         rec <= '0; end   // the DTR uses the data bus
rel   <= rn;
rel_d <= rdn;
// the CPU's critical beat and the read beats each port still waits for
if (dlv_v && !dlv_port && dlv_crit) cpu_crit <= 1'b0;
if (acc_cpu && !cpu_bq.r.we) cpu_crit <= 1'b1;
if (dlv_v && dlv_port && dlv_crit) dma_crit <= 1'b0;
if (acc_dma && !dma_bq.r.we) dma_crit <= 1'b1;
cpu_rd <= cpu_rd + ((acc_cpu && !cpu_bq.r.we) ? (cpu_bq.r.size == BZ_LINE ? 3'd4 : 3'd1) : 3'd0)
                 - ((dlv_v && !dlv_port) ? 3'd1 : 3'd0);
dma_rd <= dma_rd + ((acc_dma && !dma_bq.r.we) ? (dma_bq.r.size == BZ_LINE ? 3'd4 : 3'd1) : 3'd0)
                 - ((dlv_v && dlv_port) ? 3'd1 : 3'd0);
// the lock
if (lk_st != 2'd0 && lk_cnt != '1) lk_cnt <= lk_cnt + 6'd1;
if (lk_st == 2'd2 && !lk_hold) lk_st <= 2'd0;
if (lk_st == 2'd3 && !wbusy[1]) lk_st <= 2'd0;                  // the DMAC pair's write is done (its end Bcyc)
if ((acc_cpu && cpu_bq.r.lock && !cpu_bq.r.we) || (acc_dma && dma_bq.r.lock && !dma_bq.r.we)) begin
  lk_st <= 2'd1; lk_port <= acc_dma; lk_cnt <= 6'd1;
end else if (lk_st == 2'd1 && ((acc_cpu && !lk_port) || (acc_dma && lk_port)))
  lk_st <= lk_port ? 2'd3 : (LOCK_HOLD > 0) ? 2'd2 : 2'd0;
// a manual reset: the core's pipeline is cleared, so a CPU pair's write never comes -- drop its lock / hold (no
// accept happens during rst.man); a DMAC pair completes (its unit in progress does, SOC.md 2.3)
if (rst.man && !lk_port) begin lk_st <= 2'd0; lk_cnt <= '0; end
// bus release
unique case (bst)
  B_OWN: if (rel_go) begin
    if (banks_open) begin bst <= B_PALL; bcnt <= pall_len; end
    else bst <= B_REL;

// Standby (SOC.md 2.5, hm 9.5.2).  bce stops; the IRL synchroniser and filter then sample on `rtc_tick` (IRL wakes
// standby only with the RTC running), the NMI synchroniser samples every cycle (the NMI detector runs without the bus
// clock [P]), and `wake_stby` is computed from those and the live on-chip levels except the WDT interval timer (ITI),
// each against the synchronised IMASK, with MAI masking everything (the NMI too) while the NMI pin is low [M 19.4.3].
// With MAI = 1 a pin transition in standby generates no NMI at all [M 19.4.3: "an NMI interrupt is not generated by a
// transition at the NMI pin.  Therefore, standby cannot be cleared by an NMI interrupt while the MAI bit is set to 1"]:
// the edge detector latches nothing (no nmi_pend, no nmi_evt), so neither the pin rising again nor a later standby exit
// by another source exposes an NMI.  An NMI latched before standby stays pending (masked while the pin is low) [P].
module v1_intc import v1_soc_pkg::*; (
  input  logic      clk,
  /* verilator lint_off UNUSEDSIGNAL */          // rst.pin implies rst.por; rst.cpu (CPU-only reset) holds the INTC
  input  rst_t      rst,                         // ce.pce: the register strobes arrive in pce cycles by construction
  input  clken_t    ce,
  input  p4s_req_t  pq,                          // blk / dma / off[27:18]: the bridge's decode already selected the
  /* verilator lint_on UNUSEDSIGNAL */           // block (a translated or DMAC 0x1FDxxxxx access looks the same)
  output p4s_rsp_t  pr,
  input  logic [3:0] irl_n,                      // IRL3-0 pins (1111 = no request)
  input  logic      nmi_pin,
  input  irq_src_t  src,                         // on-chip request levels (a module-stopped unit drives 0)
  input  logic [3:0] sr_imask,                   // SR.IMASK with the S-stage write-through (SOC.md 3.4)
  input  logic      sr_bl,
  input  logic      asleep,                      // the core is in SLEEP: BL does not block (hm 5.7, 9.3.2)
  input  logic      stby,                        // standby (v1_cpg): bce is stopped
  input  logic      rtc_tick,                    // the RTC's 32 kHz sampling tick (v1_rtc)
  output irq_t      irq,
  /* verilator lint_off UNUSEDSIGNAL */          // irq_ack: every on-chip / IRL request is a level the handler clears
  input  logic      irq_ack,                     // at its source; the INTC keeps no per-request state to release
  /* verilator lint_on UNUSEDSIGNAL */
  input  logic      nmi_ack,                     // the NMI entry reached S: clear the NMI latch and ICR.NMIB [M]
