    T(NOWRITE, "pre-sort, not written out: grey 0.3, a white stripe 0.7 at x 8..15, depth write off; keep Z: twice?");
    zadd(ListType_Opaque, 0, 0, 32, 32, Z3, 0xff808080); zadd_nw(ListType_Translucent, 8, 0, 8, 32, Z7, 0x80ffffff);
    T(KEEPZ | SAME, "");
