    // Consumer-owned. Own cache line.
    DECL_ALIGN(TA_RING_LINE) volatile u32 read_pub;
    u32 write_cache;           // consumer's cached copy of write_pub

    DECL_ALIGN(TA_RING_LINE) u8 data[TA_RING_BYTES];
};

